import { test, expect } from '@playwright/test'
import {
  loginAsAdminOnce,
  waitForPageLoading,
  gotoHashPath,
  collectAppRoutes
} from '../fixtures/auth-helpers.js'
import { disableDriverGuide } from '../fixtures/company-helpers.js'
import { dismissErrorDialog, waitForPageLoading as waitLoading } from '../fixtures/auth-helpers.js'
import { assertListPageReady, clickQueryIfPresent, waitForListTableReady } from '../fixtures/crud-helpers.js'

const MENU = {
  module: '预售资金',
  title: '银行名单',
  filePath: 'supervision/bank/superviseBank/index'
}

function isSuperviseBankListResponse(response) {
  return (
    response.url().includes('/prefund/workBank/selectTJgWorkBankAndNumList') &&
    response.request().method() === 'POST'
  )
}

async function gotoSuperviseBankList(page) {
  const routes = await collectAppRoutes(page)
  const matched = routes.filter((r) => r.filePath === MENU.filePath)
  expect(matched.length, `未找到菜单路由 ${MENU.filePath}`).toBeGreaterThan(0)
  const listRoute = matched.find((r) => !String(r.path).includes(':tableid')) || matched[0]
  const listPromise = page.waitForResponse(isSuperviseBankListResponse, { timeout: 45000 })
  await gotoHashPath(page, listRoute.path)
  await disableDriverGuide(page)
  await dismissErrorDialog(page)
  await assertListPageReady(page, MENU)
  const body = await (await listPromise).json()
  await waitForListTableReady(page)
  return { body, path: listRoute.path }
}

async function pickFirstBankNameOption(page) {
  const select = page.locator('.search-form-container .el-form-item').filter({ hasText: '银行名称' }).locator('.el-select').first()
  await expect(select).toBeVisible({ timeout: 15000 })
  await select.click()
  const option = page.locator('.zs-select-popper .el-select-dropdown__item, .el-select-dropdown:not(.is-hidden) .el-select-dropdown__item').filter({ hasNotText: '无数据' }).first()
  await expect(option).toBeVisible({ timeout: 15000 })
  const label = (await option.innerText()).trim()
  await option.click()
  return label
}

test.describe.serial('Bug6099 银行名单筛选后查看详情返回', () => {
  test.beforeEach(async ({ page }) => {
    await loginAsAdminOnce(page)
  })

  test('筛选 → 查看 → 返回后列表仍有数据', async ({ page }) => {
    const { body, path } = await gotoSuperviseBankList(page)
    expect(body.code, body.msg).toBe(200)
    const initialTotal = body.data?.total ?? body.total ?? body.data?.rows?.length ?? 0
    test.skip(initialTotal === 0, '本地环境银行名单无数据，跳过')

    const bankLabel = await pickFirstBankNameOption(page)
    const filteredPromise = page.waitForResponse(isSuperviseBankListResponse, { timeout: 45000 })
    await clickQueryIfPresent(page)
    const filteredBody = await (await filteredPromise).json()
    expect(filteredBody.code, filteredBody.msg).toBe(200)
    const filteredRows = filteredBody.data?.rows || filteredBody.rows || []
    expect(filteredRows.length, '筛选后列表为空，无法验证返回场景').toBeGreaterThan(0)

    const viewLink = page.locator('.el-table__body-wrapper tbody tr').first().locator('a, .el-link').first()
    await expect(viewLink).toBeVisible({ timeout: 15000 })
    await viewLink.click()
    await waitForPageLoading(page)
    await expect(page.locator('.detail-container').first()).toBeVisible({ timeout: 20000 })

    await page.goBack({ waitUntil: 'domcontentloaded' })
    await waitLoading(page)
    await dismissErrorDialog(page)

    const afterBackPromise = page.waitForResponse(isSuperviseBankListResponse, { timeout: 45000 })
    await expect(page).toHaveURL(new RegExp(path.replace(/\//g, '\\/').replace(/:/g, '\\:')), { timeout: 20000 })
    const afterBackBody = await (await afterBackPromise).json()
    expect(afterBackBody.code, afterBackBody.msg).toBe(200)
    const afterRows = afterBackBody.data?.rows || afterBackBody.rows || []
    expect(afterRows.length, `返回后列表为空（筛选银行：${bankLabel}）`).toBeGreaterThan(0)

    const emptyText = page.locator('.el-table__empty-text').filter({ hasText: '暂无数据' })
    await expect(emptyText).toHaveCount(0)
  })
})

